using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Windows.Forms;
using AuroraProxy;
class NodeSortUiTests {
 static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static int count;
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;Console.WriteLine("PASS: "+label);}
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,Flags).GetValue(o);}
 static IEnumerable<Control> Controls(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Controls(child))yield return nested;}}
 [STAThread] static int Main(){string root=Path.Combine(Path.GetTempPath(),"aurora-sort-"+Guid.NewGuid().ToString("N"));try{Application.EnableVisualStyles();using(var main=new MainForm(new Store(root),true)){main.Show();main.PreviewPage(2);Application.DoEvents();var data=new Dictionary<string,object>();var names=Enumerable.Range(0,100).Select(i=>"Node "+i.ToString("000")).ToArray();data["Sort group"]=new Dictionary<string,object>{{"all",names},{"now",names[50]}};for(int i=0;i<100;i++){var d=new Dictionary<string,object>{{"type","http"}};if(i!=98)d["history"]=new object[]{new Dictionary<string,object>{{"delay",i==99?0:(100-i)/2+1}}};data[names[i]]=d;}typeof(MainForm).GetField("proxyData",Flags).SetValue(main,data);typeof(MainForm).GetMethod("FillGroups",Flags).Invoke(main,null);Application.DoEvents();var nodes=Field<ListView>(main,"nodes");var sort=Controls(main).OfType<ComboBox>().First(x=>x.Items.Contains("延迟：低到高"));Check(nodes.Items[0].Text==names[0],"default keeps subscription order");nodes.Items[50].Selected=true;nodes.Items[50].Focused=true;nodes.TopItem=nodes.Items[40];Application.DoEvents();string top=nodes.TopItem.Text;sort.SelectedIndex=1;Application.DoEvents();Check(nodes.Items[0].Text==names[97]&&nodes.Items[1].Text==names[95]&&nodes.Items[2].Text==names[96],"ascending uses numeric delay with stable ties");Check(nodes.Items[98].Text==names[98]&&nodes.Items[99].Text==names[99],"untested and timed out stay last");Check(nodes.SelectedItems[0].Text==names[50]&&nodes.FocusedItem.Text==names[50],"sort preserves selected and focused node");Check(nodes.TopItem.Text==top,"sort preserves viewport anchor");sort.SelectedIndex=2;Application.DoEvents();Check(nodes.Items[0].Text==names[0]&&nodes.Items[98].Text==names[98],"descending keeps unavailable nodes last");var history=(object[])((Dictionary<string,object>)data[names[50]])["history"];
((Dictionary<string,object>)history[0])["delay"]=600;typeof(MainForm).GetMethod("FillNodes",Flags,null,new Type[]{typeof(bool)},null).Invoke(main,new object[]{true});Check(nodes.Items[0].Text==names[50]&&nodes.SelectedItems[0].Text==names[50],"new test results re-sort while preserving selection");sort.SelectedIndex=0;Check(nodes.Items[50].Text==names[50],"original order can be restored");typeof(ListView).GetMethod("OnColumnClick",Flags).Invoke(nodes,new object[]{new ColumnClickEventArgs(2)});Check(sort.SelectedIndex==1,"latency column toggles ascending");typeof(ListView).GetMethod("OnColumnClick",Flags).Invoke(nodes,new object[]{new ColumnClickEventArgs(2)});Check(sort.SelectedIndex==2,"latency column toggles descending");main.PreviewPage(3);main.PreviewPage(2);Application.DoEvents();sort=Controls(main).OfType<ComboBox>().First(x=>x.Items.Contains("延迟：低到高"));Check(sort.SelectedIndex==2,"page navigation remembers sort mode");main.Close();}Console.WriteLine("Completed "+count+" node sorting checks.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}
